def t(key: str, **kw) -> str:
    lang = LANG.get()
    s = T.get(key, {}).get(lang) or T.get(key, {}).get("uz") or key
    return s.format(**kw) if kw else s


def ty(typ: str) -> str:
    """Tranzaksiya turi nomi."""
    k = "ty_" + typ
    return t(k) if k in T else typ


