_LEG_SORTED = sorted(LEGACY, key=lambda x: -len(x[0]))


def loc(text: str, lang: str) -> str:
    """Eski inglizcha admin matnini tanlangan tilga o'giradi."""
    if not text or lang not in ("uz", "ru"):
        return text
    i = 1 if lang == "uz" else 2
    for row in _LEG_SORTED:
        if row[0] in text:
            text = text.replace(row[0], row[i])
    return text
